@n2 syntax.nominal head="Intro"
@r2 syntax.relation marker="with" from=$c1 to=$n3
@n3 syntax.nominal head="text" dependent="Main"
@r3 syntax.relation marker="at" from=$c1 to=$n4
@n4 syntax.nominal head="level" dependent="3"
